// Hand-written. Not generated by Speakeasy.
package provider

import (
	"testing"

	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

func obj(fields map[string]tftypes.Type, values map[string]tftypes.Value) tftypes.Value {
	return tftypes.NewValue(tftypes.Object{AttributeTypes: fields}, values)
}

// The rule: a plan that differs from prior state only by unknowns is not a
// change. Anything known and different is.
func TestOnlyUnknownsDiffer(t *testing.T) {
	types := map[string]tftypes.Type{
		"name":   tftypes.String,
		"count":  tftypes.Number,
		"things": tftypes.List{ElementType: tftypes.String},
	}
	list := func(vals ...string) tftypes.Value {
		out := make([]tftypes.Value, 0, len(vals))
		for _, v := range vals {
			out = append(out, tftypes.NewValue(tftypes.String, v))
		}
		return tftypes.NewValue(tftypes.List{ElementType: tftypes.String}, out)
	}
	state := obj(types, map[string]tftypes.Value{
		"name":   tftypes.NewValue(tftypes.String, "a"),
		"count":  tftypes.NewValue(tftypes.Number, 1),
		"things": list("x", "y"),
	})

	for name, tc := range map[string]struct {
		plan tftypes.Value
		want bool
	}{
		"identical": {state, true},
		"a computed attribute went unknown": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "a"),
			"count":  tftypes.NewValue(tftypes.Number, tftypes.UnknownValue),
			"things": list("x", "y"),
		}), true},
		"every attribute went unknown": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
			"count":  tftypes.NewValue(tftypes.Number, tftypes.UnknownValue),
			"things": tftypes.NewValue(tftypes.List{ElementType: tftypes.String}, tftypes.UnknownValue),
		}), true},
		"a real edit to a string": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "b"),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("x", "y"),
		}), false},
		"a real edit alongside an unknown": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "b"),
			"count":  tftypes.NewValue(tftypes.Number, tftypes.UnknownValue),
			"things": list("x", "y"),
		}), false},
		// The ordering modifiers run before this, so a list Authlete reorders
		// already matches. One that still differs genuinely moved.
		"a list that still differs": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "a"),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("y", "x"),
		}), false},
		"an element added": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "a"),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("x", "y", "z"),
		}), false},
		"a value became null": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, nil),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("x", "y"),
		}), false},
	} {
		t.Run(name, func(t *testing.T) {
			if got := onlyUnknownsDiffer(tc.plan, state); got != tc.want {
				t.Errorf("onlyUnknownsDiffer = %v, want %v", got, tc.want)
			}
		})
	}
}

// Nested objects are where the computed attributes of a client's extension
// live, so the walk has to reach them.
func TestOnlyUnknownsDiffersWalksNested(t *testing.T) {
	inner := tftypes.Object{AttributeTypes: map[string]tftypes.Type{"n": tftypes.Number}}
	outer := map[string]tftypes.Type{"ext": inner}

	state := obj(outer, map[string]tftypes.Value{
		"ext": tftypes.NewValue(inner, map[string]tftypes.Value{"n": tftypes.NewValue(tftypes.Number, 1)}),
	})
	unknownInside := obj(outer, map[string]tftypes.Value{
		"ext": tftypes.NewValue(inner, map[string]tftypes.Value{"n": tftypes.NewValue(tftypes.Number, tftypes.UnknownValue)}),
	})
	changedInside := obj(outer, map[string]tftypes.Value{
		"ext": tftypes.NewValue(inner, map[string]tftypes.Value{"n": tftypes.NewValue(tftypes.Number, 2)}),
	})

	if !onlyUnknownsDiffer(unknownInside, state) {
		t.Error("a nested unknown should not count as a change")
	}
	if onlyUnknownsDiffer(changedInside, state) {
		t.Error("a nested edit was missed, so a real change would be suppressed")
	}
}
